import {LitElement,html} from "lit";
import {createAtom} from "@tanstack/lit-store";
const results=[];
const check=(mode,name,ok,detail)=>results.push({mode,name,ok,detail});

class NativeFormController{
 internals; sub;
 constructor(host,store,mode){
  this.host=host;this.store=store;this.mode=mode;
  this.internals=host.attachInternals();host.addController(this);
 }
 sync(){
  const s=this.store.get();this.internals.setFormValue(s.value,s.value);
  const invalid=s.required&&!s.value;
  const anchor=this.host.shadowRoot?.querySelector("input")??undefined;
  this.internals.setValidity(invalid?{valueMissing:true}:{},invalid?"Enter a value.":"",anchor);
 }
 hostConnected(){this.sync();if(this.mode==="sync")this.sub=this.store.subscribe(()=>this.sync());}
 hostDisconnected(){this.sub?.unsubscribe();this.sub=undefined;}
 hostUpdate(){if(this.mode==="render")this.sync();}
 hostUpdated(){this.sync();}
 associated(){this.sync();}
 disabled(value){this.host.setState({effectiveDisabled:value});}
 reset(){this.host.value=this.host.getAttribute("value")??"";}
 restore(value){if(typeof value==="string")this.host.value=value;}
}
function formHost(Base){
 return class extends Base{
  static formAssociated=true;
  formAssociatedCallback(){this.formControl.associated();}
  formDisabledCallback(value){this.formControl.disabled(value);}
  formResetCallback(){this.formControl.reset();}
  formStateRestoreCallback(value,mode){this.formControl.restore(value,mode);}
 };
}
for(const mode of ["sync","render"]){
 class Probe extends formHost(LitElement){
  state=createAtom({value:"",required:false,effectiveDisabled:false});
  formControl=new NativeFormController(this,this.state,mode);
  allowUpdate=true;
  get value(){return this.state.get().value;}
  set value(v){this.setState({value:v});}
  get required(){return this.state.get().required;}
  set required(v){this.setState({required:v});}
  get name(){return this.getAttribute("name")??"";}
  set name(v){this.setAttribute("name",v);}
  get disabled(){return this.hasAttribute("disabled");}
  set disabled(v){this.toggleAttribute("disabled",v);}
  setState(patch){this.state.set(s=>({...s,...patch}));if(mode==="sync")this.formControl.sync();this.requestUpdate();}
  shouldUpdate(){return this.allowUpdate;}
  render(){const s=this.state.get();return html`<input aria-label="Probe" .value=${s.value} ?required=${s.required} ?disabled=${s.effectiveDisabled}>`;}
 }
 customElements.define("native-form-"+mode,Probe);
 const form=document.createElement("form");form.id="form-"+mode;document.body.append(form);
 const el=document.createElement("native-form-"+mode);el.name="entry";form.append(el);await el.updateComplete;
 el.value="new";check(mode,"immediate submission after property write",new FormData(form).get("entry")==="new");
 await el.updateComplete;el.value="";el.required=true;check(mode,"immediate required validity",!form.checkValidity());
 await el.updateComplete;el.value="valid";check(mode,"immediate valid state",form.checkValidity());
 await el.updateComplete;el.allowUpdate=false;el.value="gated";await el.updateComplete;check(mode,"submission remains current when render is rejected",new FormData(form).get("entry")==="gated");
 el.allowUpdate=true;el.requestUpdate();await el.updateComplete;
 el.setAttribute("value","reset");form.reset();check(mode,"reset submission is immediate",el.value==="reset"&&new FormData(form).get("entry")==="reset");await el.updateComplete;
 const fieldset=document.createElement("fieldset");form.append(fieldset);fieldset.append(el);await el.updateComplete;fieldset.disabled=true;await el.updateComplete;check(mode,"fieldset disables inner control and submission",el.shadowRoot.querySelector("input").disabled&&!new FormData(form).has("entry"));
 check(mode,"fieldset does not set own disabled attribute",!el.disabled);
 fieldset.disabled=false;await el.updateComplete;check(mode,"fieldset re-enable restores control",!el.shadowRoot.querySelector("input").disabled&&new FormData(form).has("entry"));
 el.disabled=true;fieldset.disabled=true;fieldset.disabled=false;await el.updateComplete;check(mode,"own disabled survives parent changes",el.disabled&&el.shadowRoot.querySelector("input").disabled);el.disabled=false;
 const legend=document.createElement("legend");fieldset.prepend(legend);legend.append(el);fieldset.disabled=true;await el.updateComplete;check(mode,"first legend exception",!el.shadowRoot.querySelector("input").disabled&&new FormData(form).has("entry"));fieldset.disabled=false;
 document.body.append(el);el.setAttribute("form",form.id);await el.updateComplete;check(mode,"external form owner",el.formControl.internals.form===form&&new FormData(form).get("entry")===el.value);
 el.name="renamed";check(mode,"name assignment updates submission immediately",new FormData(form).has("renamed")&&!new FormData(form).has("entry"));
 el.formStateRestoreCallback("restored","restore");check(mode,"explicit restoration callback updates store and submission",el.state.get().value==="restored"&&new FormData(form).get("renamed")==="restored");
 await el.updateComplete;el.remove();el.value="detached";document.body.append(el);await el.updateComplete;check(mode,"detach write and reconnect",new FormData(form).get("renamed")==="detached");
 const count=new FormData(form).getAll("renamed").length;check(mode,"one submission despite inner native input",count===1,count);
 form.remove();el.remove();
}
document.querySelector("#results").textContent=JSON.stringify({runtime:"Chromium; scratch native form mechanisms",results},null,2);
